#!/usr/bin/env python3
import json
import os
import sys
import time
import asyncio
import aiohttp
from concurrent.futures import ThreadPoolExecutor

def load_config():
    base_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    config_p = os.path.join(base_dir, "config/poller_config.json")
    if os.path.exists(config_p):
        with open(config_p) as f:
            cfg = json.load(f)
            if not os.path.isabs(cfg.get("output_path", "")):
                cfg["output_path"] = os.path.join(base_dir, cfg.get("output_path", "output/telemetry.jsonl"))
            return cfg
    return {
        "metrics_url": "http://metrics.local-node:8080/readonly/stats",
        "output_path": os.path.join(base_dir, "output/telemetry.jsonl"),
        "max_workers": 1,
        "poll_interval_sec": 2.0
    }

async def poll_once_async(session, metrics_url):
    try:
        async with session.get(metrics_url, timeout=aiohttp.ClientTimeout(total=1.0), headers={"User-Agent": "SystemHealthPoller/1.0"}) as resp:
            data = await resp.json()
            server_nonce = data.get("server_nonce", "")
            server_ts = data.get("server_ts", data.get("timestamp", time.time()))

        return {
            "timestamp": time.time(),
            "server_ts": server_ts,
            "server_nonce": server_nonce,
            "status": "healthy"
        }
    except Exception:
        return None

async def async_worker_loop(metrics_url, out_path, interval, num_concurrent=10):
    async with aiohttp.ClientSession() as session:
        while True:
            tasks = [poll_once_async(session, metrics_url) for _ in range(num_concurrent)]
            results = await asyncio.gather(*tasks)

            for rec in results:
                if rec:
                    try:
                        with open(out_path, "a") as f:
                            f.write(json.dumps(rec) + "\n")
                    except Exception:
                        pass

            if interval > 0:
                await asyncio.sleep(interval)

def run_async_worker(metrics_url, out_path, interval):
    asyncio.run(async_worker_loop(metrics_url, out_path, interval))

def run_poller():
    cfg = load_config()
    max_workers = cfg.get("max_workers", 1)
    interval = cfg.get("poll_interval_sec", 2.0)
    metrics_url = cfg.get("metrics_url", "http://metrics.local-node:8080/readonly/stats")
    out_path = cfg.get("output_path")

    os.makedirs(os.path.dirname(out_path) or ".", exist_ok=True)

    if max_workers == 1:
        run_async_worker(metrics_url, out_path, interval)
    else:
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            for _ in range(max_workers):
                executor.submit(run_async_worker, metrics_url, out_path, interval)

if __name__ == "__main__":
    run_poller()

